import React, { useState } from 'react';

const TECH_CATEGORIES = [
  { id: 'frontend', label: 'Frontend Engineering', skills: [
    { name: 'Vue.js', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/vuejs/vuejs-original.svg' },
    { name: 'React', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/react/react-original.svg' },
    { name: 'JavaScript', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/javascript/javascript-original.svg' },
    { name: 'TypeScript', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/typescript/typescript-original.svg' },
    { name: 'Nuxt.js', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nuxtjs/nuxtjs-original.svg' },
    { name: 'Next.js', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nextjs/nextjs-original.svg' },
    { name: 'Tailwind CSS', icon: 'https://www.vectorlogo.zone/logos/tailwindcss/tailwindcss-icon.svg' },
    { name: 'Vite', icon: 'https://upload.wikimedia.org/wikipedia/commons/f/f1/Vitejs-logo.svg' },
    { name: 'Bootstrap', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/bootstrap/bootstrap-original.svg' },
  ]},
  { id: 'backend', label: 'Backend Engineering', skills: [
    { name: 'Node.js', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nodejs/nodejs-original.svg' },
    { name: 'Express', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/express/express-original.svg' },
    { name: 'Python', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/python/python-original.svg' },
    { name: 'MongoDB', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/mongodb/mongodb-original.svg' },
  ]},
  { id: 'mobile', label: 'Mobile Application Development', skills: [
    { name: 'React Native', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/react/react-original.svg' },
    { name: 'Flutter', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/flutter/flutter-original.svg' },
  ]},
  { id: 'design', label: 'Design', skills: [
    { name: 'Figma', icon: 'https://www.vectorlogo.zone/logos/figma/figma-icon.svg' },
    { name: 'Illustrator', icon: 'https://www.vectorlogo.zone/logos/adobe_illustrator/adobe_illustrator-icon.svg' },
  ]},
  { id: 'data', label: 'Data & Backend Platforms', skills: [] },
  { id: 'plugins', label: 'Plugins', skills: [] },
  { id: 'cms', label: 'CMS', skills: [] },
  { id: 'cloud', label: 'Cloud', skills: [] },
  { id: 'erp', label: 'ERP', skills: [] },
  { id: 'deployment', label: 'Deployment', skills: [] },
  { id: 'ecommerce', label: 'E-commerce', skills: [] },
  { id: 'qa', label: 'QA', skills: [] },
  { id: 'frameworks', label: 'Frameworks & Libraries', skills: [] },
  { id: 'nocode', label: 'No Code Apps', skills: [] },
];

export default function Technologies() {
  const [activeTab, setActiveTab] = useState('frontend');
  const activeCategory = TECH_CATEGORIES.find(cat => cat.id === activeTab) || TECH_CATEGORIES[0];

  return (
    <section className="p-8 font-sans">
      <div className="max-w-[1400px] mx-auto">
        <div className="flex border border-black min-h-[800px] bg-white">

          {/* Sidebar */}
          <div className="w-[320px] flex-shrink-0 border-r border-black bg-[#EAEAEA] flex flex-col">
            {TECH_CATEGORIES.map((cat) => {
              const isActive = activeTab === cat.id;
              return (
                <button
                  key={cat.id}
                  onClick={() => setActiveTab(cat.id)}
                  className={`px-6 py-5 text-left border-b border-black transition-colors flex items-center ${
                    isActive 
                      ? 'bg-white text-black relative z-10 w-[calc(100%+1px)]' 
                      : 'text-gray-500 hover:bg-gray-200'
                  }`}
                >
                  <span className="text-[13px] font-mono font-bold uppercase tracking-[0.15em] leading-snug">
                    {cat.label}
                  </span>
                </button>
              );
            })}
          </div>

          {/* Content */}
          <div className="flex-1 p-10 bg-white">
            <h2 className="text-[2.5rem] font-bold mb-10 text-black tracking-tight">
              {activeCategory.label}
            </h2>

            {activeCategory.skills.length > 0 && (
              <div className="grid grid-cols-4 border-l border-t border-black">
                {activeCategory.skills.map((skill) => (
                  <div 
                    key={skill.name} 
                    className="border-r border-b border-black flex flex-col items-center justify-center p-12 hover:bg-gray-50 transition-colors"
                  >
                    <div className="w-16 h-16 flex items-center justify-center mb-6">
                      <img 
                        src={skill.icon} 
                        alt={skill.name} 
                        className="max-w-full max-h-full object-contain" 
                      />
                    </div>
                    <span className="text-xs font-bold font-mono uppercase text-center tracking-[0.15em]">
                      {skill.name}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>

        </div>
      </div>
    </section>
  );
}
